CREATE TABLE fba_approvals (updated_at timestamp, product_id int4, buy_price_ex_vat numeric, buy_box_price numeric, profit_per_unit numeric, roi numeric, qty int4, total_buy_price numeric, approved_at timestamp, purchase_date date, purchase_made bool, created_at timestamp, id int4 NOT NULL, supplier_order_ref text, asin text NOT NULL, sourced_by text NOT NULL, product_name text, supplier_name text, supplier_url text, approval_status text, approved_by text, purchased_by text, rejection_reason text, asin_link text, stb_id text);

