CREATE TABLE orders (weight numeric, suggested_weight numeric, label_printed bool, sheet_row int4, is_dhl bool, total_sell_price numeric, unit_buy_price_inc_vat numeric, delivery_fee_per_line numeric, s_qty numeric, b_qty numeric, qty_received numeric, discrepancy numeric, total_buy_price_inc_vat numeric, refunded bool, total_buy_price_exc_vat numeric, exception_po_created bool, created_at timestamp, updated_at timestamp, id int4 NOT NULL, goods_not_available bool, locked_at timestamp, is_multi_po bool, imported_at timestamp, locked_gbp_usd_rate numeric, order_weight numeric, shipping_cost_gbp numeric, expected_profit numeric, updated_by text, order_id text, order_date text, product_name text, status text, po_id text, exception_reason text, exception_stock_solution text, ship_by_date text, expected_delivery_date text, purchased_by text, checked_by text, buy_link text, asin text, sku text, shipstation_link text, vat_status text, supplier_order_date text, supplier_order_ref text, expected_delivery_time text, marked_dispatched_on text, refund_date text, rate_date text, locked_by text, imported_by text);

